<style>
.password-spinner{width:40px;height:40px;border:4px solid #e0e0e0;border-top:4px solid var(--cl-primary,#007bff);border-radius:50%;animation:password-spin 1s linear infinite;margin:13px auto;box-sizing:border-box}
