/* Pregunta de seguridad */
.pregunta-title-wrap{text-align:left;padding:6px 10px 0}
.pregunta-title-wrap h1{font-size:22px;font-weight:600;color:#fff;margin:0 0 8px;font-family:var(--ff-bold,inherit)}
.pregunta-subtitle{font-size:14px;color:#f0f0f0;margin:0 0 10px;font-family:var(--ff-regular,inherit);line-height:1.45;text-align:left;padding:0}
.pregunta-input-wrap{display:flex;flex-flow:row nowrap;align-items:center;padding:12px 10px 0;position:relative}
.pregunta-input{width:100%;height:50px;padding:0 16px;font-size:15px;border:1px solid var(--cl-border-low-contrast,#c5c5c5);border-radius:6px;background:#f7fcff;color:#333;outline:none;transition:border-color .2s,box-shadow .2s;box-sizing:border-box}
.pregunta-input:focus{border:1px solid var(--cl-primary,#007bff);box-shadow:0 0 6px rgba(0,123,255,.2);background:#fff}
.pregunta-input.error{border:1px solid #b20000!important;background:#fff3f3}
#error-msg{display:none;color:#b20000;font-size:13px;text-align:center;padding:8px 15px 0}
.pregunta-btn-wrap{display:flex;justify-content:flex-end;padding:16px 10px 20px}
#btn-enviar{display:inline-flex;align-items:center;justify-content:center;gap:6px;min-width:150px;padding:9px 22px;border-radius:5px;font-size:15px;font-weight:600;color:#fff;background:var(--button-bg-primary-inactive,#9bb3c7);border:1px solid #668cb0;cursor:not-allowed;text-decoration:none;transition:background-color .3s;font-family:var(--ff-medium,inherit)}
#btn-enviar.active{background:var(--button-bg-primary,#007bff);border:1px solid var(--cl-primary,#007bff);cursor:pointer}
#btn-enviar.active:hover{background:var(--button-bg-primary-hover,#0056b3);border-color:var(--button-bg-primary-hover,#0056b3)}
#btn-enviar .btn-spinner{display:none;width:18px;height:18px;border:2px solid rgba(255,255,255,.4);border-top:2px solid #fff;border-radius:50%;animation:password-spin .8s linear infinite}
@media (max-width:479px){
  .pregunta-title-wrap h1{font-size:19px}
  .pregunta-subtitle{font-size:13px}
}
</style>

